CREATE LIGHTNING REST TABLE wb_ny_gdp_mktp_kd_zg_usa FROM WORLDBANK_REST REQUEST(
    endpoint "https://api.worldbank.org/v2/country/USA/indicator/NY.GDP.MKTP.KD.ZG?format=json&date=2015:2025&per_page=100",
    method "get",
