CACHE TABLE worldbank_rest.wb_ny_gdp_mktp_kd_zg_usa;

CREATE SCHEMASTORE VIEW us_macro_indicators WITH CONTAINER worldbank AS
SELECT country_code, indicator_id, indicator_name, year, value
FROM (
    SELECT countryiso3code AS country_code, indicator.id AS indicator_id, indicator.value AS indicator_name, CAST(`date` AS INT) AS year, CAST(`value` AS DOUBLE) AS value
    FROM worldbank_rest.wb_fp_cpi_totl_zg_usa WHERE indicator IS NOT NULL
    UNION ALL
    SELECT countryiso3code AS country_code, indicator.id AS indicator_id, indicator.value AS indicator_name, CAST(`date` AS INT) AS year, CAST(`value` AS DOUBLE) AS value
    FROM worldbank_rest.wb_ne_con_prvt_kd_zg_usa WHERE indicator IS NOT NULL
    UNION ALL
    SELECT countryiso3code AS country_code, indicator.id AS indicator_id, indicator.value AS indicator_name, CAST(`date` AS INT) AS year, CAST(`value` AS DOUBLE) AS value
    FROM worldbank_rest.wb_ny_gdp_mktp_kd_zg_usa WHERE indicator IS NOT NULL
) m;
